import React, { useState } from 'react';
import { ChevronDown, ChevronRight, Sparkles } from 'lucide-react';

const faqItems = [
  {
    id: 1,
    question: "Are your pizzas wood-fired?",
    answer:
      "Absolutely! Our wood-fired ovens are a centerpiece of our restaurant, cooking each pie to perfection with just the right balance of smokiness and crust.",
  },
  {
    id: 2,
    question: "Do you offer gluten-free options?",
    answer: "Yes, we have several gluten-free pizzas and pasta dishes. Please inform your server at the time of ordering.",
  },
  {
    id: 3,
    question: "Is there a dress code?",
    answer:
      "We embrace a sophisticated yet relaxed vibe. Think stylish casual with an emphasis on comfort and style.",
  },
  {
    id: 4,
    question: "How is your wine sourced?",
    answer:
      "Our sommelier has curated an extensive list of natural wines from small producers around the globe, ensuring authentic flavors and sustainable sourcing.",
  },
  {
    id: 5,
    question: "Can I bring my pet?",
    answer:
      "We believe that enjoying great food should be a family affair! Pets are welcome in our outdoor seating area with a small fee.",
  },
];

export default function Faq() {
  const [isOpen, setIsOpen] = useState(false);

  const toggleAccordion = (id) => {
    setIsOpen((prevOpen) => {
      const newOpen = { ...prevOpen, [id]: !prevOpen[id] };
      if (Object.values(newOpen).filter((val) => val).length > 2) {
        return { [id]: false };
      }
      return newOpen;
    });
  };

  return (
    <div className="w-full bg-white/5 p-8 sm:p-12 lg:p-16 max-w-7xl mx-auto rounded-2xl shadow-2xl shadow-indigo-500/50 backdrop-blur-xl">
      <div className="relative mb-12 sm:mb-16 text-center">
        <h2 className="text-2xl sm:text-3xl font-bold text-slate-100 tracking-tight mb-4">
          <span className="inline-block bg-gradient-to-r from-indigo-500 to-violet-600 bg-clip-text text-transparent">
            Frequently Asked Questions
          </span>
        </h2>
        <p className="text-slate-400 max-w-md mx-auto">
          Explore the details that make Casa Verde an unforgettable dining experience.
        </p>
        <div className="h-1 w-20 bg-white/10 rounded-full mt-8 mb-12 border border-white/20" />
      </div>

      <div className="space-y-8 sm:space-y-10">
        {faqItems.map((item) => (
          <div
            key={item.id}
            className="group relative border border-white/10 rounded-2xl p-6 hover:scale-[1.02] transition-transform duration-300 hover:border-white/20 hover:shadow-2xl"
          >
            <div className="flex justify-between items-start mb-4">
              <h3 className="text-lg font-semibold text-slate-300 flex-1 group-hover:text-amber-400 transition-colors duration-300">
                {item.question}
                <span className="inline-flex items-center gap-1.5 text-slate-400">
                  {isOpen[item.id] ? (
                    <ChevronRight className="w-4 h-4 text-slate-500 animate-bounce" />
                  ) : (
                    <ChevronDown className="w-4 h-4 text-slate-500" />
                  )}
                </span>
              </h3>
              <div className="w-12 h-12 rounded-xl bg-white/5 flex items-center justify-center text-amber-400 group-hover:bg-white/10 transition-all duration-300">
                <Sparkles className="w-5 h-5" />
              </div>
            </div>
            {isOpen[item.id] && (
              <div className="space-y-3 text-slate-400">
                {item.answer.split('\n').map((line, idx) => (
                  <p key={idx} className="first:mt-2">
                    {line}
                  </p>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
